(function(global) {
  'use strict';

  function MiniQuery(elements) {
    this.elements = Array.isArray(elements) ? elements : Array.from(elements || []);
  }

  MiniQuery.prototype.each = function(callback) {
    this.elements.forEach(function(el, index) {
      callback.call(el, index, el);
    });
    return this;
  };

  MiniQuery.prototype.on = function(event, handler) {
    return this.each(function() {
      this.addEventListener(event, handler);
    });
  };

  MiniQuery.prototype.val = function(value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el.value : undefined;
    }
    return this.each(function() {
      this.value = value;
    });
  };

  MiniQuery.prototype.text = function(value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el.textContent : undefined;
    }
    return this.each(function() {
      this.textContent = value;
    });
  };

  MiniQuery.prototype.html = function(value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el.innerHTML : undefined;
    }
    return this.each(function() {
      this.innerHTML = value;
    });
  };

  MiniQuery.prototype.append = function(content) {
    return this.each(function() {
      if (typeof content === 'string') {
        this.insertAdjacentHTML('beforeend', content);
      } else if (content instanceof Node) {
        this.appendChild(content.cloneNode(true));
      }
    });
  };

  MiniQuery.prototype.empty = function() {
    return this.each(function() {
      this.innerHTML = '';
    });
  };

  MiniQuery.prototype.show = function() {
    return this.each(function() {
      this.classList.remove('is-hidden');
      this.style.display = '';
    });
  };

  MiniQuery.prototype.hide = function() {
    return this.each(function() {
      this.style.display = 'none';
    });
  };

  MiniQuery.prototype.attr = function(name, value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el.getAttribute(name) : undefined;
    }
    return this.each(function() {
      this.setAttribute(name, value);
    });
  };

  MiniQuery.prototype.data = function(name, value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el.dataset[name] : undefined;
    }
    return this.each(function() {
      this.dataset[name] = value;
    });
  };

  MiniQuery.prototype.addClass = function(name) {
    return this.each(function() {
      this.classList.add(name);
    });
  };

  MiniQuery.prototype.removeClass = function(name) {
    return this.each(function() {
      this.classList.remove(name);
    });
  };

  MiniQuery.prototype.toggleClass = function(name, force) {
    return this.each(function() {
      this.classList.toggle(name, force);
    });
  };

  MiniQuery.prototype.closest = function(selector) {
    var el = this.elements[0];
    return el ? $(el.closest(selector)) : $([]);
  };

  MiniQuery.prototype.find = function(selector) {
    if (!this.elements[0]) {
      return $([]);
    }
    return $(this.elements[0].querySelectorAll(selector));
  };

  MiniQuery.prototype.prop = function(name, value) {
    if (value === undefined) {
      var el = this.elements[0];
      return el ? el[name] : undefined;
    }
    return this.each(function() {
      this[name] = value;
    });
  };

  function $(selector) {
    if (typeof selector === 'function') {
      if (document.readyState !== 'loading') {
        selector();
      } else {
        document.addEventListener('DOMContentLoaded', selector);
      }
      return new MiniQuery([]);
    }
    if (selector instanceof MiniQuery) {
      return selector;
    }
    if (selector instanceof Node || selector === window || selector === document) {
      return new MiniQuery([selector]);
    }
    if (selector instanceof NodeList || Array.isArray(selector)) {
      return new MiniQuery(selector);
    }
    return new MiniQuery(document.querySelectorAll(selector));
  }

  $.ajax = function(options) {
    var url = options.url;
    var method = (options.method || options.type || 'GET').toUpperCase();
    var headers = options.headers || {};
    var data = options.data;
    var fetchOptions = {
      method: method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers)
    };
    if (data !== undefined) {
      fetchOptions.body = typeof data === 'string' ? data : JSON.stringify(data);
    }
    return fetch(url, fetchOptions)
      .then(function(response) {
        if (!response.ok) {
          var error = new Error('HTTP ' + response.status);
          error.response = response;
          throw error;
        }
        return response.json().catch(function() { return null; });
      })
      .then(function(payload) {
        if (typeof options.success === 'function') {
          options.success(payload);
        }
        return payload;
      })
      .catch(function(error) {
        if (typeof options.error === 'function') {
          options.error(error);
        } else {
          console.error('MiniQuery AJAX error:', error);
        }
        throw error;
      });
  };

  $.extend = function(target, source) {
    return Object.assign(target, source);
  };

  global.$ = $;
  global.jQuery = $;
})(typeof window !== 'undefined' ? window : this);
